CREATE temporary TABLE IF NOT EXISTS `rdoList` (
    rdo varchar(30)
    )

LOAD DATA local INFILE
#{path}
INTO TABLE `return_master`
FIELDS TERMINATED BY ','  ENCLOSED BY '"'
LINES TERMINATED BY '\n'
IGNORE 1 LINES;

LOAD DATA local INFILE
#{path}
INTO TABLE ${tableName}
FIELDS TERMINATED BY ',' ENCLOSED BY '"'
LINES TERMINATED BY '\n'
IGNORE #{skip} LINES;
